document.addEventListener("click",function(e){var t=e.target.closest("[data-copy-api-key]");if(!t)return;var n=t.dataset.copyApiKey;navigator.clipboard.writeText(n).then(function(){alert("API Key copied to clipboard!")}).catch(function(e){alert("Failed to copy API Key.");console.error(e)})});document.addEventListener("submit",function(e){var t=e.target.closest("[data-confirm]");if(!t)return;var n=t.dataset.confirm;if(!confirm(n))e.preventDefault()});document.addEventListener("click",function(e){var t=e.target.closest("[data-confirm]");if(!t||t.tagName==="FORM")return;var n=t.dataset.confirm;if(!confirm(n))e.preventDefault()});
